$('#addDomain').addEventListener('click',()=>{readConfig();state.domains.push({id:crypto.randomUUID(),domain:'',zoneId:''});renderDomainProfiles();document.querySelector('.domain-profile-row:last-child .domain-name')?.focus();});$('#domainProfiles').addEventListener('click',async event=>{const button=event.target.closest('.remove-domain');if(!button)return;const row=button.closest('.domain-profile-row');const domainName=row?.querySelector('.domain-name')?.value.trim()||'此域名';if(!await askConfirm('删除域名配置','确定删除 '+domainName+' 的配置吗？保存后不会再管理该域名。','删除配置',true))return;readConfig();state.domains=state.domains.filter(profile=>profile.id!==row?.dataset.domainId);state.activeDomainId='';renderDomainProfiles();});$('#saveDomains').addEventListener('click',()=>saveConfig($('#domainsStatus'),'保存域名配置'));
async function saveAdminPath(){const previous=state.adminPath||'/admin';try{setStatus($('#adminPathStatus'),'保存访问路径中…');await persistConfig();setStatus($('#adminPathStatus'),'访问路径已保存');notify('访问路径已保存');if(state.adminPath&&state.adminPath!==previous)location.assign(state.adminPath+(location.hash||'#dashboard'));}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#adminPathStatus'),message,true);notify(message,'error');}}
const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
function notify(text,type='success'){if(!text)return;const region=$('#toastRegion');if(!region)return;const toast=document.createElement('div');toast.className='toast '+(type==='error'?'error':'success');const icon=document.createElement('span');icon.className='toast-icon';icon.textContent=type==='error'?'!':'✓';const message=document.createElement('span');message.className='toast-text';message.textContent=text;const close=document.createElement('button');close.type='button';close.className='toast-close';close.textContent='×';close.setAttribute('aria-label','关闭提示');close.addEventListener('click',()=>toast.remove());toast.append(icon,message,close);region.append(toast);window.setTimeout(()=>toast.remove(),4200);}
function setStatus(element,text,bad=false){if(!element)return;element.textContent=text||'';element.classList.toggle('ok',Boolean(text)&&!bad&&!String(text).includes('中…'));element.classList.toggle('err',bad);element.classList.toggle('loading',Boolean(text)&&!bad&&String(text).includes('中…'));}
const baseNotify=notify;notify=(text,type='success')=>{const dnsDialog=$('#dnsDialog');if(dnsDialog?.open){setStatus($('#dnsFormStatus'),text,type==='error');return;}baseNotify(text,type);};
function setBusy(selector,busy){const button=$(selector);if(!button)return;button.disabled=busy;button.classList.toggle('is-loading',busy);button.setAttribute('aria-busy',String(busy));}
async function api(path,options={}){const request={...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}};const response=await fetch(path,request);const body=await response.json().catch(()=>({}));if(response.status===401&&path!=='/api/auth/login'){const wasLoggedIn=!$('#app').classList.contains('hidden');$('#app').classList.add('hidden');$('#login').classList.remove('hidden');throw Error(wasLoggedIn?'登录已过期，请重新登录':'未登录');}if(!response.ok)throw Error(body.error||('HTTP '+response.status));return body;}
function formatTtl(ttl){return ttl===60?'自动 · 60 秒':ttl==null?'—':'手动 · '+String(ttl)+' 秒';}
function syncDnsName(){const name=$('#dnsName');if(name)name.value=state.defaultDomain||'';}
function renderConfig(){const domain=$('#defaultDomain');if(domain)domain.value=state.defaultDomain||'';const zone=$('#cfZoneId');if(zone)zone.value=state.cfZoneId||'';const token=$('#cfApiToken');if(token){token.value='';token.placeholder=state.hasCfApiToken?'已配置 Token（留空保持）':'尚未配置 Token';}const bot=$('#telegramBotToken');if(bot){bot.value='';bot.placeholder=state.hasTelegramBotToken?'已配置 Token（留空保持）':'尚未配置 Bot Token';}const secret=$('#telegramWebhookSecret');if(secret){secret.value='';secret.placeholder=state.hasTelegramWebhookSecret?'已配置 Secret（留空保持）':'尚未配置 Webhook Secret';}const ids=$('#telegramAllowedUserIds');if(ids)ids.value=(state.telegramAllowedUserIds||[]).join('\n');const configStatus=$('#telegramConfigStatus');if(configStatus)configStatus.textContent='Bot Token：'+(state.hasTelegramBotToken?'已配置':'未配置')+' · Webhook Secret：'+(state.hasTelegramWebhookSecret?'已配置':'未配置')+' · 白名单：'+(state.telegramAllowedUserIds||[]).length+' 个用户';const sources=$('#sources');if(sources)sources.innerHTML=state.ipSources.length?state.ipSources.map((source,index)=>'<div class="source" data-index="'+index+'"><input class="s-url" placeholder="https://…" value="'+esc(source.url)+'"><label><input class="s-enabled" type="checkbox" '+(source.enabled?'checked':'')+'> 启用</label><button type="button" class="danger remove-source">删除</button></div>').join(''):'<p class="hint">还没有配置来源，可添加公开 IP 来源。</p>';const manual=$('#manualIps');if(manual)manual.value=state.manualIps.join('\n');const sourceCount=$('#sourceCount');if(sourceCount)sourceCount.textContent=String(state.ipSources.length);const manualCount=$('#manualCount');if(manualCount)manualCount.textContent=String(state.manualIps.length);syncDnsName();const domainStatus=$('#domainStatus');if(domainStatus)domainStatus.textContent=state.defaultDomain?'当前域名：'+state.defaultDomain:'尚未配置默认域名';}
function readConfig(){state.defaultDomain=$('#defaultDomain').value.trim();state.cfZoneId=$('#cfZoneId').value.trim();state.cfApiToken=$('#cfApiToken').value||undefined;state.telegramBotToken=$('#telegramBotToken').value||undefined;state.telegramWebhookSecret=$('#telegramWebhookSecret').value||undefined;state.telegramAllowedUserIds=$('#telegramAllowedUserIds').value.split(/[\s,]+/).map(value=>value.trim()).filter(value=>/^\d+$/.test(value)).slice(0,50);state.ipSources=[...document.querySelectorAll('.source')].map((element,index)=>({...state.ipSources[index],url:element.querySelector('.s-url').value.trim(),enabled:element.querySelector('.s-enabled').checked}));state.manualIps=$('#manualIps').value.split(/[\s,]+/).map(value=>value.trim()).filter(Boolean);}
async function persistConfig(){readConfig();Object.assign(state,await api('/api/config',{method:'PUT',body:JSON.stringify(state)}));renderConfig();}
async function saveConfig(element,label){try{setStatus(element,label+'中…');await persistConfig();setStatus(element,label+'成功');notify(label+'成功');await loadDns();}catch(error){const message=error instanceof Error?error.message:String(error);setStatus(element,message,true);notify(message,'error');}}
async function loadConfig(rethrow=false){try{Object.assign(state,await api('/api/config'));renderConfig();$('#login').classList.add('hidden');$('#app').classList.remove('hidden');await loadDns();}catch(error){const message=error instanceof Error?error.message:String(error);if(message.includes('登录已过期')||message==='未登录')setStatus($('#loginStatus'),message,true);else setStatus($('#runtimeStatus'),message,true);if(rethrow)throw error;}}
function showPage(page){document.querySelectorAll('.page').forEach(element=>element.classList.toggle('active',element.id===page));document.querySelectorAll('.nav button').forEach(element=>element.classList.toggle('active',element.dataset.page===page));$('#pageTitle').textContent=page==='settings'?'全局设置':'仪表盘';document.body.dataset.page=page;if(page==='dashboard')loadDns();scrollToTop();}
function updateDnsHint(){const hint=$('#dnsRuleHint');if(hint)hint.textContent=$('#dnsType').value==='CNAME'?'CNAME 会同步创建泛 CNAME，并清理两侧同名的 A/AAAA。':'保存后会同步创建或更新对应类型的泛记录；可用类型：A、AAAA、CNAME。';}
function isDnsIpv4(value){const parts=value.split('.');return parts.length===4&&parts.every(part=>/^(0|[1-9]\d*)$/.test(part)&&Number(part)<=255);}
function isDnsIpv6(value){if(!value.includes(':'))return false;const clean=value.split('%',1)[0];if(!/^[0-9a-f:]+$/i.test(clean))return false;const double=clean.indexOf('::');if(double!==-1&&clean.indexOf('::',double+2)!==-1)return false;const groups=clean.split(':').filter(Boolean);if(groups.some(group=>group.length>4))return false;return double!==-1?groups.length<8:groups.length===8;}
function detectDnsType(value){const content=value.trim();return isDnsIpv4(content)?'A':isDnsIpv6(content)?'AAAA':'CNAME';}
function syncDnsType(){const content=$('#dnsContent').value.trim();if(!content)return;$('#dnsType').value=detectDnsType(content);updateDnsHint();}
function renderDns(){const filter=($('#dnsFilter').value||'').trim().toLowerCase();const records=dnsState.records.filter(record=>[record.type,record.name,record.content].join(' ').toLowerCase().includes(filter));const rows=$('#dnsRows');if(!rows)return;if(!records.length){rows.innerHTML='<tr><td colspan="7" class="empty">'+(filter?'没有匹配的 DNS 记录':'暂无可管理的 DNS 记录')+'</td></tr>';}else{rows.innerHTML=records.map(record=>'<tr><td><span class="badge">'+esc(record.type)+'</span></td><td class="record-name">'+esc(record.name)+'</td><td class="record-content" title="'+esc(record.content)+'">'+esc(record.content)+'</td><td>'+esc(formatTtl(record.ttl))+'</td><td>'+(record.proxied?'橙云':'灰云')+'</td><td>'+(record.comment==='preferred-domain-manager'||(record.tags||[]).includes('preferred-domain-manager')?'<span class="badge managed">优选托管</span>':'<span class="badge">手动</span>')+'</td><td><div class="actions"><button type="button" class="secondary edit-dns" data-id="'+esc(record.id)+'">编辑</button><button type="button" class="danger delete-dns" data-id="'+esc(record.id)+'">删除</button></div></td></tr>').join('');}const count=$('#dnsCount');if(count)count.textContent=String(dnsState.records.length);}
const baseRenderDns=renderDns;renderDns=()=>{baseRenderDns();document.querySelectorAll('#dnsRows tr').forEach(row=>{if(row.cells.length<7)return;const ttl=row.cells[3];const proxy=row.cells[4];ttl.innerHTML='<span class="meta-chip ttl-chip">'+esc(ttl.textContent.trim())+'</span>';const proxied=proxy.textContent.includes('橙');proxy.innerHTML='<span class="meta-chip proxy-chip'+(proxied?' active':'')+'">'+(proxied?'Cloudflare 代理':'仅 DNS')+'</span>';});};
async function loadDns(){if(dnsState.loading)return;if(!state.defaultDomain||!state.cfZoneId||!state.hasCfApiToken){dnsState.records=[];renderDns();setStatus($('#dnsStatus'),'请先保存默认域名、Zone ID 和 API Token');return;}dnsState.loading=true;setBusy('#refreshDns',true);try{setStatus($('#dnsStatus'),'加载中…');const result=await api('/api/dns/records');dnsState.records=result.records||[];renderDns();setStatus($('#dnsStatus'),'共 '+dnsState.records.length+' 条主域名记录');}catch(error){dnsState.records=[];renderDns();const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}finally{dnsState.loading=false;setBusy('#refreshDns',false);}}
function openDns(record){syncDnsName();dnsState.editingId=record?.id||null;$('#dnsDialogTitle').textContent=record?'编辑 DNS 记录':'新建 DNS 记录';$('#dnsType').value=record?.type||'A';$('#dnsContent').value=record?.content||'';$('#dnsTtl').value='自动 · 60 秒';const ttlLabel=$('#dnsTtl')?.previousElementSibling;if(ttlLabel)ttlLabel.textContent='缓存时间';const proxyLabel=$('#dnsProxied')?.parentElement;if(proxyLabel&&proxyLabel.lastChild)proxyLabel.lastChild.textContent='仅 DNS 解析';setStatus($('#dnsFormStatus'),'');syncDnsType();updateDnsHint();$('#dnsDialog').showModal();setTimeout(()=>$('#dnsContent').focus(),0);}
function closeDns(){const dialog=$('#dnsDialog');if(dialog.open)dialog.close();dnsState.editingId=null;}
function reopenDns(){const dialog=$('#dnsDialog');if(!dialog.open)dialog.showModal();setTimeout(()=>$('#dnsContent').focus(),0);}
function normalizeDnsContent(value){return String(value||'').trim().toLowerCase().replace(/\.$/,'');}
function findDuplicateDnsRecord(type,content,editingId){const normalized=normalizeDnsContent(content);const domain=String(state.defaultDomain||'').toLowerCase();return dnsState.records.find(record=>record.id!==editingId&&String(record.name||'').toLowerCase()===domain&&record.type===type&&normalizeDnsContent(record.content)===normalized);}
async function submitDns(event){event.preventDefault();const button=$('#saveDns');const editing=Boolean(dnsState.editingId);if(button)button.disabled=true;try{const content=$('#dnsContent').value.trim();if(!content)throw Error('记录内容不能为空');const type=detectDnsType(content);$('#dnsType').value=type;updateDnsHint();const duplicate=findDuplicateDnsRecord(type,content,dnsState.editingId);if(duplicate)throw Error('该 '+type+' 记录已经存在：'+duplicate.content+'，无需重复添加。');const sameType=dnsState.records.find(record=>record.id!==dnsState.editingId&&record.name.toLowerCase()===String(state.defaultDomain||'').toLowerCase()&&record.type===type);if(!editing&&type==='CNAME'&&sameType){const dnsDialog=$('#dnsDialog');if(dnsDialog.open)dnsDialog.close();const overwrite=await askConfirm('CNAME 记录已存在','当前域名已有 CNAME 记录：\n'+sameType.content+'\n继续保存会替换它，并同步更新泛 CNAME。','替换保存',true);if(!overwrite){reopenDns();return;}}await api('/api/dns/records'+(editing?'/'+encodeURIComponent(dnsState.editingId):''),{method:editing?'PUT':'POST',body:JSON.stringify({type,name:state.defaultDomain,content,proxied:false})});closeDns();await loadDns();setStatus($('#dnsStatus'),editing?'记录已更新':'记录已创建');notify((editing?'记录已更新为 ':'记录已创建，类型为 ')+type);if(button)button.blur();}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}finally{if(button)button.disabled=false;}}
async function deleteDns(id){const record=dnsState.records.find(item=>item.id===id);if(!record)return;const confirmed=await askConfirm('删除 DNS 记录','确定删除 '+record.type+' '+record.name+' 吗？\n对应泛记录也会同步删除。','删除记录',true);if(!confirmed)return;try{await api('/api/dns/records/'+encodeURIComponent(id),{method:'DELETE'});await loadDns();setStatus($('#dnsStatus'),'记录已删除');notify('记录已删除');}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}}
let actionBusy=false;async function runAction(path,label){if(actionBusy)return;actionBusy=true;['#preview','#sync','#saveConfig'].forEach(selector=>setBusy(selector,true));try{setStatus($('#status'),label+'中…');await persistConfig();const result=await api(path,{method:'POST',body:'{}'});$('#output').textContent=JSON.stringify(result,null,2);const message=result.result?.skippedCname?'检测到 CNAME，已跳过 IP 同步':label+'完成';setStatus($('#status'),message);notify(message);await loadDns();}catch(error){const message=error instanceof Error?error.message:String(error);$('#output').textContent=message;setStatus($('#status'),message,true);notify(message,'error');}finally{actionBusy=false;['#preview','#sync','#saveConfig'].forEach(selector=>setBusy(selector,false));}}
